/**
 * Review report for a visual-baseline refresh (COR-1512; new code, not a port).
 *
 * Compares each regenerated baseline with the committed one it replaces:
 * - a changed pixel is one pixelmatch flags at the suite's `threshold: 0.1`,
 *   and the ratio is changed pixels over the new image's width times height;
 * - unchanged means pixel-identical (byte-identical is a subset);
 * - a dimension change is reported as such, with no ratio;
 * - added baselines (no committed counterpart) are listed separately;
 * - orphans (committed, but regenerated by no test) are removed after a full,
 *   unfiltered update and kept after a scoped one, which never selected the
 *   tests that own them (`OrphanDisposition`, COR-1574). An orphan named `<theme>-<viewport>-default.png` whose
 *   `-assertion.png` counterpart was added is a rename (the cinder-era
 *   `default` fixture became `assertion`); renames are compared pixel by pixel
 *   and classified like changes. Every other orphan is listed with the evidence
 *   that no current fixture or spec names it.
 *
 * Writes `baseline-diff-report.json`, `baseline-diff-report.md`, and a diff
 * image per changed or renamed-and-changed baseline. `filesToApply` and
 * `filesToDelete` name exactly what a refresh commits, so unchanged rewrites
 * keep their original bytes.
 */
import { existsSync, readFileSync } from 'node:fs';
import { mkdir, readdir } from 'node:fs/promises';
import { dirname, join, relative } from 'node:path';

import pixelmatch from 'pixelmatch';
import { PNG } from 'pngjs';

import type { ApplyDecision, NonPassingTest, SuiteResults } from './suite-results.ts';

/** The suite's `toHaveScreenshot` threshold (`SNAPSHOT_DIFF_OPTIONS` in @lostgradient/testing). */
export const PIXEL_THRESHOLD = 0.1;
/** Changed baselines above this ratio need a review classification. */
export const CLASSIFICATION_RATIO = 0.01;

export type BaselineComparison =
  | { path: string; kind: 'unchanged'; byteIdentical: boolean }
  | {
      path: string;
      kind: 'changed';
      changedPixels: number;
      totalPixels: number;
      ratio: number;
    }
  | {
      path: string;
      kind: 'dimensions';
      oldSize: { width: number; height: number };
      newSize: { width: number; height: number };
    }
  | { path: string; kind: 'added' };

export type RenamedBaseline = { from: string; to: string; comparison: BaselineComparison };

export type OrphanEvidence = {
  path: string;
  slug: string;
  fixture: string | undefined;
  slugInManifest: boolean;
  fixtureInManifest: boolean;
  fixtureNamedInSpecs: boolean;
};

/** The current fixture manifest and spec sources, read from the rendered commit. */
export type NamingSources = {
  manifestFixtures: ReadonlyMap<string, readonly string[]>;
  specText: string;
};

export type SuiteOutcome = {
  exitCode: number;
  results: SuiteResults | undefined;
  decision: ApplyDecision;
};

/** A committed baseline a non-passing test owns: kept from git, never deleted. */
export type RestoredBaseline = { path: string; test: string; reason: string };

/**
 * What a refresh does with its orphans: a full, unfiltered run removes them; a run scoped by
 * `CINDER_TEST_COMPONENTS` or by forwarded Playwright arguments keeps them (COR-1574).
 */
export type OrphanDisposition = 'deleted' | 'kept';

/** The selection an update run rendered: its component scope and forwarded Playwright arguments. */
export type RunScope = {
  componentScope: 'all' | readonly string[];
  playwrightArguments: readonly string[];
};

export const FULL_RUN: RunScope = { componentScope: 'all', playwrightArguments: [] };

/** A full, unfiltered run removes its orphans; any scoped run keeps them. */
export function orphanDisposition(scope: RunScope): OrphanDisposition {
  return scope.componentScope === 'all' && scope.playwrightArguments.length === 0
    ? 'deleted'
    : 'kept';
}

export type BaselineDiffReport = {
  comparisons: BaselineComparison[];
  scope: RunScope;
  /** `deleted` after a full, unfiltered run; `kept` after a scoped one. */
  orphanDisposition: OrphanDisposition;
  /** Committed baselines no test regenerated, removed or kept as `orphanDisposition` says. */
  orphaned: string[];
  /** Committed baselines a failing or skipped test may not have written: kept, not orphaned. */
  restored: RestoredBaseline[];
  renamed: RenamedBaseline[];
  unpairedOrphans: OrphanEvidence[];
  counts: {
    regenerated: number;
    changed: number;
    dimensionChanged: number;
    unchanged: number;
    byteIdentical: number;
    added: number;
    renamed: number;
    renamedUnchanged: number;
    renamedChanged: number;
    orphans: number;
    unpairedOrphans: number;
    restored: number;
    needsClassification: number;
  };
};

/** The 1-minute load and logical CPU count at the start and end of the rendering run. */
export type RunHostLoad = {
  start: { oneMinuteLoad: number; logicalCpus: number };
  end: { oneMinuteLoad: number; logicalCpus: number };
};

export type PairComparison = {
  comparison: BaselineComparison;
  diffImage?: Buffer;
};

/** Compare one committed baseline with its regenerated replacement. */
export function compareBaselinePair(
  path: string,
  oldBytes: Buffer | undefined,
  newBytes: Buffer,
): PairComparison {
  if (oldBytes === undefined) return { comparison: { path, kind: 'added' } };
  if (oldBytes.equals(newBytes)) {
    return { comparison: { path, kind: 'unchanged', byteIdentical: true } };
  }
  const before = PNG.sync.read(oldBytes);
  const after = PNG.sync.read(newBytes);
  if (before.width !== after.width || before.height !== after.height) {
    return {
      comparison: {
        path,
        kind: 'dimensions',
        oldSize: { width: before.width, height: before.height },
        newSize: { width: after.width, height: after.height },
      },
    };
  }
  const diff = new PNG({ width: after.width, height: after.height });
  const changedPixels = pixelmatch(before.data, after.data, diff.data, after.width, after.height, {
    threshold: PIXEL_THRESHOLD,
  });
  if (changedPixels === 0) {
    return { comparison: { path, kind: 'unchanged', byteIdentical: false } };
  }
  const totalPixels = after.width * after.height;
  return {
    comparison: {
      path,
      kind: 'changed',
      changedPixels,
      totalPixels,
      ratio: changedPixels / totalPixels,
    },
    diffImage: PNG.sync.write(diff),
  };
}

/** Every `.png` under `directory`, as forward-slash paths relative to it, sorted. */
export async function listBaselines(directory: string): Promise<string[]> {
  if (!existsSync(directory)) return [];
  const entries = await readdir(directory, { recursive: true, withFileTypes: true });
  return entries
    .filter((entry) => entry.isFile() && entry.name.endsWith('.png'))
    .map((entry) => relative(directory, join(entry.parentPath, entry.name)).split('\\').join('/'))
    .toSorted();
}

/**
 * Normalize the container's `find` output (repository-relative paths) to paths
 * relative to the Linux baseline directory.
 */
export function parseRegeneratedList(text: string, baselineDirectory: string): string[] {
  const prefix = `${baselineDirectory.replace(/\/$/, '')}/`;
  return [
    ...new Set(
      text
        .split('\n')
        .map((line) => line.trim().replace(/^\.\//, ''))
        .filter((line) => line.endsWith('.png'))
        .map((line) => (line.startsWith(prefix) ? line.slice(prefix.length) : line)),
    ),
  ].toSorted();
}

export type BuildReportOptions = {
  oldDirectory: string;
  newDirectory: string;
  regenerated: readonly string[];
  diffDirectory?: string;
  namingSources?: NamingSources;
  /** Tests that failed or were skipped in the update run, which may not have written a baseline. */
  nonPassing?: readonly NonPassingTest[];
  /** Spec sources by repository-relative file under the tests directory. */
  specSources?: ReadonlyMap<string, string>;
  /** The run's selection, which decides whether its orphans are removed. Defaults to a full run. */
  scope?: RunScope;
};

/**
 * The non-passing test that owns a committed baseline, if any. A sweep test's title
 * names the component and the image (`components.playwright.ts › button › dark-mobile-primary`
 * owns `button/dark-mobile-primary.png` and its `-resting` partner); a spec that names its
 * screenshots owns one whose name it quotes.
 */
export function owningTest(
  baseline: string,
  nonPassing: readonly NonPassingTest[],
  specSources: ReadonlyMap<string, string> = new Map(),
): NonPassingTest | undefined {
  const slug = baseline.split('/')[0] ?? '';
  const stem = (baseline.split('/').at(-1) ?? '').replace(/\.png$/, '').replace(/-resting$/, '');
  const quoted = (text: string, name: string) =>
    ["'", '"', '`'].some((quote) => text.includes(`${quote}${name}${quote}`));
  return nonPassing.find((test) => {
    const segments = test.title.split(' › ');
    if (segments.includes(slug) && segments.includes(stem)) return true;
    const source = specSources.get(test.file);
    return source !== undefined && (quoted(source, stem) || quoted(source, `${slug}/${stem}`));
  });
}

const RENAMED_FROM = /-default\.png$/;
const BASELINE_NAME = /^(?:light|dark)-(?:mobile|tablet|desktop)-(.+)\.png$/;

/** The `-assertion.png` name a cinder-era `-default.png` baseline was renamed to, if any. */
export function renameTarget(orphan: string): string | undefined {
  return RENAMED_FROM.test(orphan) ? orphan.replace(RENAMED_FROM, '-assertion.png') : undefined;
}

/** Facts showing no current fixture or spec names an orphan. */
export function orphanEvidence(path: string, sources: NamingSources | undefined): OrphanEvidence {
  const slug = path.split('/')[0] ?? '';
  const fixture = BASELINE_NAME.exec(path.split('/').at(-1) ?? '')?.[1];
  const fixtures = sources?.manifestFixtures.get(slug);
  const quoted = (name: string) =>
    ["'", '"', '`'].some((quote) => sources?.specText.includes(`${quote}${name}${quote}`));
  return {
    path,
    slug,
    fixture,
    slugInManifest: fixtures !== undefined,
    fixtureInManifest: fixture !== undefined && (fixtures?.includes(fixture) ?? false),
    fixtureNamedInSpecs: fixture !== undefined && quoted(fixture),
  };
}

async function writeDiff(directory: string | undefined, path: string, image: Buffer | undefined) {
  if (image === undefined || directory === undefined) return;
  const target = join(directory, path.replace(/\.png$/, '-diff.png'));
  await mkdir(dirname(target), { recursive: true });
  await Bun.write(target, image);
}

export async function buildBaselineDiffReport(
  options: BuildReportOptions,
): Promise<BaselineDiffReport> {
  const regenerated = new Set(options.regenerated);
  const comparisons: BaselineComparison[] = [];
  for (const path of [...regenerated].toSorted()) {
    const oldPath = join(options.oldDirectory, path);
    const oldBytes = existsSync(oldPath) ? readFileSync(oldPath) : undefined;
    const { comparison, diffImage } = compareBaselinePair(
      path,
      oldBytes,
      readFileSync(join(options.newDirectory, path)),
    );
    comparisons.push(comparison);
    await writeDiff(options.diffDirectory, path, diffImage);
  }
  const added = new Set(
    comparisons.filter((comparison) => comparison.kind === 'added').map((c) => c.path),
  );
  const committed = await listBaselines(options.oldDirectory);
  const restored: RestoredBaseline[] = [];
  const orphaned: string[] = [];
  for (const path of committed.filter((candidate) => !regenerated.has(candidate))) {
    const owner = owningTest(path, options.nonPassing ?? [], options.specSources);
    if (owner === undefined) orphaned.push(path);
    else restored.push({ path, test: owner.title, reason: owner.reason });
  }
  const renamed: RenamedBaseline[] = [];
  const unpairedOrphans: OrphanEvidence[] = [];
  for (const from of orphaned) {
    const to = renameTarget(from);
    if (to === undefined || !added.has(to)) {
      unpairedOrphans.push(orphanEvidence(from, options.namingSources));
      continue;
    }
    const { comparison, diffImage } = compareBaselinePair(
      to,
      readFileSync(join(options.oldDirectory, from)),
      readFileSync(join(options.newDirectory, to)),
    );
    renamed.push({ from, to, comparison });
    await writeDiff(options.diffDirectory, to, diffImage);
  }
  const renamedTargets = new Set(renamed.map((rename) => rename.to));
  const of = (kind: BaselineComparison['kind']) =>
    comparisons.filter((comparison) => comparison.kind === kind);
  const unchanged = of('unchanged');
  const renamedUnchanged = renamed.filter((rename) => rename.comparison.kind === 'unchanged');
  const scope = options.scope ?? FULL_RUN;
  return {
    comparisons,
    scope,
    orphanDisposition: orphanDisposition(scope),
    orphaned,
    renamed,
    unpairedOrphans,
    restored,
    counts: {
      regenerated: comparisons.length,
      changed: of('changed').length,
      dimensionChanged: of('dimensions').length,
      unchanged: unchanged.length,
      byteIdentical: unchanged.filter(
        (comparison) => 'byteIdentical' in comparison && comparison.byteIdentical,
      ).length,
      added: [...added].filter((path) => !renamedTargets.has(path)).length,
      renamed: renamed.length,
      renamedUnchanged: renamedUnchanged.length,
      renamedChanged: renamed.length - renamedUnchanged.length,
      orphans: orphaned.length,
      unpairedOrphans: unpairedOrphans.length,
      restored: restored.length,
      needsClassification: needsClassification([
        ...comparisons,
        ...renamed.map((rename) => rename.comparison),
      ]).length,
    },
  };
}

/** Changed baselines above the classification ratio, plus every dimension change. */
export function needsClassification(
  comparisons: readonly BaselineComparison[],
): BaselineComparison[] {
  return comparisons.filter(
    (comparison) =>
      comparison.kind === 'dimensions' ||
      (comparison.kind === 'changed' && comparison.ratio > CLASSIFICATION_RATIO),
  );
}

/** The baselines a refresh writes: pixel-changed, dimension-changed, added, and renamed. */
export function filesToApply(report: BaselineDiffReport): string[] {
  return report.comparisons
    .filter((comparison) => comparison.kind !== 'unchanged')
    .map((comparison) => comparison.path);
}

/** The baselines a refresh removes: every orphan, renamed or not, after a full run; none after a scoped one. */
export function filesToDelete(report: BaselineDiffReport): string[] {
  return report.orphanDisposition === 'deleted' ? [...report.orphaned] : [];
}

function percent(ratio: number): string {
  return `${(ratio * 100).toFixed(3)}%`;
}

function describeComparison(comparison: BaselineComparison): string {
  if (comparison.kind === 'changed')
    return `${comparison.changedPixels} | ${percent(comparison.ratio)}`;
  if (comparison.kind === 'dimensions') {
    return `dimensions | ${comparison.oldSize.width}x${comparison.oldSize.height} to ${comparison.newSize.width}x${comparison.newSize.height}`;
  }
  return '0 | 0.000%';
}

function classificationCell(comparison: BaselineComparison): string {
  return needsClassification([comparison]).length > 0 ? 'to classify' : 'below threshold';
}

function renderSuite(lines: string[], suite: SuiteOutcome): void {
  lines.push(
    '## Suite outcome',
    '',
    `Playwright exited ${suite.exitCode}. ${suite.decision.reason}`,
    '',
  );
  const results = suite.results;
  if (results === undefined) {
    lines.push('No Playwright JSON report was produced.');
    return;
  }
  lines.push(
    `Expected ${results.expected}, unexpected ${results.unexpected}, flaky ${results.flaky}, skipped ${results.skipped}.`,
    '',
  );
  if (results.failures.length > 0) {
    lines.push('| Failing test | Kind | First error |', '| --- | --- | --- |');
    for (const failure of results.failures) {
      const error = (failure.errors[0] ?? '').replaceAll('|', '\\|');
      lines.push(
        `| \`${failure.title}\` | ${failure.screenshot ? 'screenshot' : 'behavioural'} | ${error} |`,
      );
    }
  }
  if (results.flakyTests.length > 0) {
    lines.push(
      '',
      'Flaky (passed on retry):',
      '',
      ...results.flakyTests.map((title) => `- \`${title}\``),
    );
  }
}

export type ReportContext = { hostLoad?: RunHostLoad; suite?: SuiteOutcome };

export function renderReportMarkdown(
  report: BaselineDiffReport,
  heading: string,
  context: ReportContext = {},
): string {
  const { counts } = report;
  const kept = report.orphanDisposition === 'kept';
  const Disposition = kept ? 'Kept' : 'Deleted';
  const lines = [`# ${heading}`, ''];
  const { hostLoad, suite } = context;
  if (hostLoad !== undefined) {
    const describe = (reading: RunHostLoad['start']) =>
      `${reading.oneMinuteLoad.toFixed(2)} on ${reading.logicalCpus} logical CPUs`;
    lines.push(
      `Host 1-minute load: ${describe(hostLoad.start)} at the start of the run, ${describe(hostLoad.end)} at the end.`,
      '',
    );
  }
  lines.push(
    `Pixel comparison: pixelmatch at threshold ${PIXEL_THRESHOLD}. The ratio is changed pixels over the new image's width times height. Changed and renamed images above ${percent(CLASSIFICATION_RATIO)}, and every dimension change, need a classification: (a) rasterizer or toolchain drift, (b) an intentional source change never re-baselined (cite the commit), or (c) an unintended regression.`,
    '',
    '| Category | Count |',
    '| --- | --- |',
    `| Regenerated | ${counts.regenerated} |`,
    `| Changed (pixels) | ${counts.changed} |`,
    `| Dimension changed | ${counts.dimensionChanged} |`,
    `| Unchanged (pixel-identical, original bytes kept) | ${counts.unchanged} |`,
    `| Unchanged and byte-identical | ${counts.byteIdentical} |`,
    `| Added (no committed counterpart) | ${counts.added} |`,
    `| Renamed from \`-default\` to \`-assertion\` | ${counts.renamed} |`,
    `| Renamed and pixel-identical | ${counts.renamedUnchanged} |`,
    `| Renamed and changed | ${counts.renamedChanged} |`,
    `| ${Disposition} orphans (all) | ${counts.orphans} |`,
    `| ${Disposition} orphans without a rename partner | ${counts.unpairedOrphans} |`,
    `| Restored, not regenerated (owned by a failing or skipped test) | ${counts.restored} |`,
    `| Needs classification | ${counts.needsClassification} |`,
    '',
    kept
      ? `Orphans: kept ${counts.orphans} orphans. The run was scoped (component scope ${JSON.stringify(report.scope.componentScope)}, Playwright arguments ${JSON.stringify(report.scope.playwrightArguments)}), so it never selected the tests that own them; only a full, unfiltered run removes them.`
      : `Orphans: deleted ${counts.orphans} orphans after a full, unfiltered run.`,
    '',
  );
  if (suite !== undefined) {
    renderSuite(lines, suite);
    lines.push('');
  }
  const table = (title: string, rows: { path: string; comparison: BaselineComparison }[]) => {
    lines.push(`## ${title}`, '');
    if (rows.length === 0) {
      lines.push('None.', '');
      return;
    }
    lines.push(
      '| Baseline | Changed pixels | Ratio | Classification |',
      '| --- | --- | --- | --- |',
    );
    for (const row of rows) {
      lines.push(
        `| \`${row.path}\` | ${describeComparison(row.comparison)} | ${classificationCell(row.comparison)} |`,
      );
    }
    lines.push('');
  };
  const byRatio = (row: { comparison: BaselineComparison }) =>
    row.comparison.kind === 'changed'
      ? row.comparison.ratio
      : row.comparison.kind === 'dimensions'
        ? 2
        : 0;
  table(
    'Changed baselines',
    report.comparisons
      .filter((comparison) => comparison.kind === 'changed' || comparison.kind === 'dimensions')
      .map((comparison) => ({ path: comparison.path, comparison }))
      .toSorted((left, right) => byRatio(right) - byRatio(left)),
  );
  table(
    'Renamed and changed baselines (old `-default` compared with new `-assertion`)',
    report.renamed
      .filter((rename) => rename.comparison.kind !== 'unchanged')
      .map((rename) => ({ path: rename.to, comparison: rename.comparison }))
      .toSorted((left, right) => byRatio(right) - byRatio(left)),
  );
  const renamedTargets = new Set(report.renamed.map((rename) => rename.to));
  const added = report.comparisons
    .filter((comparison) => comparison.kind === 'added' && !renamedTargets.has(comparison.path))
    .map((comparison) => `- \`${comparison.path}\``);
  lines.push('## Added baselines', '', ...(added.length > 0 ? added : ['None.']), '');
  lines.push(
    '## Restored, not regenerated',
    '',
    'Committed baselines whose test failed or was skipped in the update run, so it may never have reached its screenshot. They keep their committed bytes and are not orphans.',
    '',
    ...(report.restored.length > 0
      ? report.restored.map(
          (entry) =>
            `- \`${entry.path}\`: \`${entry.test}\` (${entry.reason.replaceAll('|', '\\|')})`,
        )
      : ['None.']),
    '',
    `## ${Disposition} orphans with a rename partner`,
    '',
    ...(report.renamed.length > 0
      ? report.renamed.map((rename) => `- \`${rename.from}\` renamed to \`${rename.to}\``)
      : ['None.']),
    '',
    `## ${Disposition} orphans without a rename partner`,
    '',
    `${kept ? 'This scoped' : 'A full'} \`--update-snapshots=all\` run regenerated nothing under these names. For each: whether the component is in the fixture manifest, whether the manifest lists the fixture, and whether any spec names the fixture as a quoted string.`,
    '',
  );
  if (report.unpairedOrphans.length === 0) lines.push('None.');
  else {
    lines.push(
      '| Baseline | Component in manifest | Fixture in manifest | Fixture named in specs |',
      '| --- | --- | --- | --- |',
    );
    const yes = (value: boolean) => (value ? 'yes' : 'no');
    for (const orphan of report.unpairedOrphans) {
      lines.push(
        `| \`${orphan.path}\` | ${yes(orphan.slugInManifest)} | ${yes(orphan.fixtureInManifest)} | ${yes(orphan.fixtureNamedInSpecs)} |`,
      );
    }
  }
  return `${lines.join('\n')}\n`;
}

export async function writeBaselineDiffReport(
  report: BaselineDiffReport,
  outputDirectory: string,
  heading: string,
  context: ReportContext = {},
): Promise<{ json: string; markdown: string }> {
  await mkdir(outputDirectory, { recursive: true });
  const json = join(outputDirectory, 'baseline-diff-report.json');
  const markdown = join(outputDirectory, 'baseline-diff-report.md');
  await Bun.write(json, `${JSON.stringify({ ...report, ...context }, null, 2)}\n`);
  await Bun.write(markdown, renderReportMarkdown(report, heading, context));
  return { json, markdown };
}
